WHERE {
  ?professor a uni:Person ;
             uni:hasName ?professorName ;
             uni:worksIn ?dept .
  ?dept uni:belongsTo ?university .
  ?university uni:locatedInCountry ?country .

  ?professor uni:role ?role .
  FILTER(REGEX(?role, "^Professor"))
  FILTER(!REGEX(?role, "^Assistant Professor"))

  FILTER EXISTS {
    SELECT ?dummy
    WHERE {
      ?professor a uni:Person .
      FILTER(?professor = uni:Orfeas_Menis)
    }
  }
}
"""
results = g.query(query)
for row in results:
    print(f"Name: {row.professorName}, Country: {row.country}")
